import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');

// Load Google Font for retro billboard subtitle overlay at module level
const { fontFamily: bebasFamily } = loadBebas();

// Define exactly ONE named Zod schema


export type ILoveNYProps = Record<string, any>;

// Helper Component for decorative scanlines (Retro TV Effect)
const Scanlines: React.FC<{ enabled: boolean }> = ({ enabled }) => {
  if (!enabled) return null;
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        backgroundImage: "linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.4) 50%)",
        backgroundSize: "100% 6px",
        zIndex: 10,
        opacity: 0.45,
        transition: "none",
      }}
    />
  );
};

// Helper Component for a subtle Broadway/Cyberpunk style background grid
const GridBackground: React.FC<{ enabled: boolean }> = ({ enabled }) => {
  if (!enabled) return null;
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        backgroundImage: `
          linear-gradient(to right, rgba(255, 255, 255, 0.05) 1px, transparent 1px),
          linear-gradient(to bottom, rgba(255, 255, 255, 0.05) 1px, transparent 1px)
        `,
        backgroundSize: "60px 60px",
        backgroundPosition: "center center",
        zIndex: 1,
        transition: "none",
      }}
    />
  );
};

export const ILoveNY: React.FC<ILoveNYProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  logoUrl = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/92b42fd13e3d493f93e9561e1f35066c.svg",
  logoScale = 0.9,
  enableNeonIntro = true,
  heartBeatScaleMultiplier = 1.15,
  heartBeatFrequency = 1.2,
  glowColor = "#ff0000",
  maxGlowRadius = 40,
  strobeEnabled = true,
  strobeSpeedInFrames = 20,
  strobeColor = "#ff0844",
  strobeOpacity = 0.25,
  scanlinesEnabled = true,
  gridEnabled = true,
  subtitleText = "TIMES SQUARE, NYC",
  subtitleColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Resolve background transparent behavior
  const resolvedBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Custom high-fidelity neon flickering sequence for entry
  const neonFlicker = (f: number) => {
    if (f < 5) return 0;
    if (f >= 5 && f < 8) return 0.2;  // brief flicker
    if (f >= 8 && f < 10) return 0;   // completely dark
    if (f >= 10 && f < 15) return 0.8; // brighter flicker
    if (f >= 15 && f < 18) return 0.1; // dim
    if (f >= 18 && f < 22) return 0.9; // almost full
    if (f >= 22 && f < 25) return 0.3; // sudden drop
    return 1; // fully stabilized
  };

  // Spring physics for smooth scaled intro bounce
  const entrySpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 90,
    },
  });

  // Calculate continuous heartbeat cycles (double pulse rhythm)
  const cycleFrames = Math.max(1, Math.round(fps / heartBeatFrequency));
  const cycleIndex = frame % cycleFrames;

  let heartBeatScale = 1.0;
  if (cycleIndex < 6) {
    // Primary hard heartbeat
    heartBeatScale = interpolate(cycleIndex, [0, 3, 6], [1.0, heartBeatScaleMultiplier, 1.0], {
      extrapolateRight: "clamp",
    });
  } else if (cycleIndex >= 8 && cycleIndex < 14) {
    // Secondary softer echoing beat
    const echoMax = 1.0 + (heartBeatScaleMultiplier - 1.0) * 0.4;
    heartBeatScale = interpolate(cycleIndex, [8, 11, 14], [1.0, echoMax, 1.0], {
      extrapolateRight: "clamp",
    });
  }

  // Neon opacity combined with linear transition if neon intro is disabled
  const opacityValue = enableNeonIntro
    ? neonFlicker(frame)
    : interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // Spring entrance combined with heartbeat scaling multiplier
  const currentLogoScale = interpolate(entrySpring, [0, 1], [0.1, logoScale]) * heartBeatScale;

  // Calculate real-time glowing drop shadow radius tied to the heartbeat
  const currentGlowRadius = interpolate(
    heartBeatScale,
    [1.0, heartBeatScaleMultiplier],
    [maxGlowRadius * 0.25, maxGlowRadius],
    { extrapolateRight: "clamp" }
  );

  // Smooth decay strobe overlay calculations
  const strobeIndex = frame % strobeSpeedInFrames;
  const currentStrobeOpacity = strobeEnabled
    ? interpolate(strobeIndex, [0, strobeSpeedInFrames - 1], [strobeOpacity, 0], {
        extrapolateRight: "clamp",
      })
    : 0;

  // Title / Subtitle entrance slide up animation
  const subtitleY = interpolate(frame, [25, 45], [20, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const subtitleOpacity = interpolate(frame, [25, 40], [0, 0.8], {
    extrapolateRight: "clamp",
  });

  // Safe horizontal layout spacing & sizing rules
  const imageContainerSize = Math.min(width, height) * 0.8;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: resolvedBgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Visual Backdrop Details */}
      <GridBackground enabled={gridEnabled} />

      {/* Decay Strobe Light Overlay */}
      {strobeEnabled && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundColor: strobeColor,
            opacity: currentStrobeOpacity,
            pointerEvents: "none",
            mixBlendMode: "screen",
            zIndex: 2,
            transition: "none",
          }}
        />
      )}

      {/* Main Interactive Logo Container */}
      <div
        style={{
          width: imageContainerSize,
          height: imageContainerSize,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${currentLogoScale})`,
          opacity: opacityValue,
          filter: `drop-shadow(0px 0px ${currentGlowRadius}px ${glowColor})`,
          zIndex: 5,
          transition: "none",
        }}
      >
        <Img
          src={logoUrl}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "contain",
            transition: "none",
          }}
        />
      </div>

      {/* Optional Vintage Subtitle Tagline */}
      {subtitleText && (
        <div
          style={{
            position: "absolute",
            bottom: height * 0.08,
            fontFamily: bebasFamily,
            fontSize: Math.min(width, height) * 0.045,
            color: subtitleColor,
            letterSpacing: "6px",
            opacity: subtitleOpacity,
            transform: `translateY(${subtitleY}px)`,
            zIndex: 6,
            textAlign: "center",
            textShadow: `0 0 10px ${glowColor}66`,
            transition: "none",
          }}
        >
          {subtitleText}
        </div>
      )}

      {/* Overlay Scanlines CRT Effect */}
      <Scanlines enabled={scanlinesEnabled} />
    </AbsoluteFill>
  );
};

export default ILoveNY;